messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>3D Animation</title>
    <style>
        body { margin: 0; overflow: hidden; }
        #scene { position: absolute; top: 0; left: 0; width: 100vw; height: 100vh; }
    </style>
</head>
<body>
    <div id="scene"></div>
    <script type="module">
        import * as THREE from './three.module.js';

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.getElementById('scene').appendChild(renderer.domElement);

        const groundGeom = new THREE.PlaneGeometry(200, 10);
        const groundMat = new THREE.MeshBasicMaterial({ color: 0x888888 });
        const ground = new THREE.Mesh(groundGeom, groundMat);
        ground.rotation.x = -Math.PI/2;
        scene.add(ground);

        const skyGeom = new THREE.SphereGeometry(500, 32, 16);
        const skyMat = new THREE.MeshBasicMaterial({ color: 0x87ceeb, side: THREE.DoubleSide });
        const sky = new THREE.Mesh(skyGeom, skyMat);
        scene.add(sky);

        const finishLineGeom = new THREE.PlaneGeometry(200, 0.5);
        const finishLineMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
        const finishLine = new THREE.Mesh(finishLineGeom, finishLineMat);
        finishLine.position.y = 0;
        finishLine.rotation.x = -Math.PI/2;
        scene.add(finishLine);

        const blueCarGeom = new THREE.BoxGeometry(4, 2, 6);
        const blueCarMat = new THREE.MeshBasicMaterial({ color: 0x0000ff });
        const blueCar = new THREE.Mesh(blueCarGeom, blueCarMat);
        blueCar.position.set(-5, 1, 0);
        scene.add(blueCar);

        const redCarGeom = new THREE.BoxGeometry(4, 2, 6);
        const redCarMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
        const redCar = new THREE.Mesh(redCarGeom, redCarMat);
        redCar.position.set(-5, 1, -20);
        scene.add(redCar);

        const blueSpeed = 0.5;
        const redSpeed = 0.5;

        const animate = () => {
            requestAnimationFrame(animate);
            blueCar.position.z += blueSpeed;
            redCar.position.z += redSpeed;

            // blue car leads early
            if (blueCar.position.z < 0) {
                blueSpeed = 0.5;
                redSpeed = 0.4;
            }

            // red car accelerates and overtakes
            if (blueCar.position.z > 0) {
                redSpeed = 0.8;
            }

            // red car wins after crossing finish line
            if (redCar.position.z >= 0) {
                // reset positions to loop
                blueCar.position.set(-5, 1, -20);
                redCar.position.set(-5, 1, -20);
                blueSpeed = 0.5;
                redSpeed = 0.5;
            }

            // simple look-at camera to keep both cars in view
            const maxZ = Math.max(Math.abs(blueCar.position.z), Math.abs(redCar.position.z));
            const distance = maxZ + 10;
            const neededFov = 2 * Math.atan((10) / distance) * (180 / Math.PI);
            camera.position.z = distance + 5;
            camera.lookAt(scene.position);

            renderer.render(scene, camera);
        };
        animate();
    </script>
</body>
</html>
```
